import { sdpHasCandidates, waitForIceGathering } from "./callSignal";
import { symmetricNat, type DirectEvidence } from "./directPath";
import { wrapDataChannel, type FrameChannel } from "./frames";
import { traceLink } from "./linkTrace";
import {
  DATA_CHANNEL_ID,
  DATA_CHANNEL_LABEL,
  RTC_SIGNAL_FUTURE_MS,
  buildDataSdp,
  extractRtcParams,
  offerIsFresh,
  type SignalSight,
  parseRtcSignal,
  type RtcSignal,
} from "./signal";

/**
 * The WebRTC data link of one link: a single RTCPeerConnection carrying the
 * negotiated `ghostly/1` DataChannel. Offer and answer travel through the
 * `_rtc` record; once the channel is open Pkarr is out of the picture and all
 * application traffic flows peer to peer (or through TURN, if ICE needs it).
 */
export type DataLinkState = "idle" | "offering" | "answering" | "connecting" | "open";

export interface DataLinkOptions {
  myPubKeyZ32: string;
  peerPubKeyZ32: string;
  createPeerConnection: () => RTCPeerConnection;
  /** Publishes (or clears, with null) my `_rtc` record. */
  publishSignal: (signal: string | null) => void;
  /** Signaling in progress (or over): look fast for the peer's signal. `offer`: for the answer to this side's offer. */
  setFastPoll: (fast: boolean, offer?: boolean) => void;
  onOpen: (channel: FrameChannel) => void;
  onClose: () => void;
  onState?: (state: DataLinkState) => void;
  /**
   * How long an attempt (offer or answer out, channel not yet open) may take before it is given up, so the
   * next one can start, asked as each one starts. Default `CONNECT_TIMEOUT_MS`; a first pairing, whose contact
   * is right there reading its invite, uses a short one until it is over.
   */
  attemptTimeoutMs?: () => number | undefined;
  /**
   * The open connection went `disconnected` (true: ICE consent checks unanswered, the contact may be gone or its app
   * restarted; the connection is given `DISCONNECT_GRACE_MS`), or came back from it (false).
   */
  onDisconnected?: (disconnected: boolean) => void;
  /**
   * Whether the peer's packet, as last read, still carries its offer of that time (`RtcSignal.ts`). An answer to it
   * that did not connect is then made again (`REANSWERS`); without this, never.
   */
  offerStanding?: (offerTs: number) => boolean;
  /**
   * This side's attempt was given up because the answerer answered its offer again (its connection for the answer
   * applied here is gone), or because its answer could not be applied (`ANSWER_REFUSED_REDIALS`): the answerer is
   * there, so the caller may dial again now rather than at its next look.
   */
  onAnswerReplaced?: () => void;
  /**
   * This side's answers were refused more times in a row than it offers again at once for (`ANSWER_REFUSED_REDIALS`):
   * the WebRTC of this device takes none now (libdatachannel's race, on a loaded core), and the next offer would wait
   * the caller's backoff, minutes after a few failures. Nothing about the network: the answerer was there each time.
   */
  onAnswersRefused?: () => void;
  /**
   * What an attempt said about direct connections from this device (`directPath.ts`): it opened (and, later, closed);
   * it did not connect and this device had no public candidate for it, or a public port per STUN server; or this
   * side's offer was answered and no path connected.
   */
  onDirect?: (evidence: DirectEvidence) => void;
}

/**
 * An attempt ended from outside (another transport went live first) that had both descriptions for this long and no
 * connection says what one that failed does: a path that exists connects within a second or two.
 */
export const STALLED_EVIDENCE_MS = 5_000;
/** A candidate another network can reach: server reflexive (STUN answered), relayed (TURN), or learnt from the peer. */
const PUBLIC_CANDIDATE = /^a=candidate:.* typ (srflx|relay|prflx)\b/m;

export const CONNECT_TIMEOUT_MS = 90_000;
const ICE_GATHERING_TIMEOUT_MS = 5_000;
/**
 * An offer with its host candidates waits this long at most for a server reflexive one (STUN answered), not
 * `ICE_GATHERING_TIMEOUT_MS`. Where the STUN servers answer, they do in some 50 ms (0.44 s an offer took here, with the
 * settle); where they do not, every offer of a first pairing waited the full 5 s, twice when the inviter offered too
 * (One's e2e runs: 13 offers of 89 at 5 s, 9 more at 1.3-3 s, 2026-10-05). An offer without one still connects to most
 * contacts (their checks learn this side's address from its own); behind a restricted NAT on the contact's side it may
 * not, and the next offer of the chat then waits as long as it takes (`fullGather`). An answer is bounded the same way:
 * it waited the full 5 s, and two CLI daemons whose STUN server swallowed every request went live 10 s after the offer
 * rather than 2 s (calls bug hunt, 2026-10-12).
 */
export const OFFER_HOST_GATHER_MS = 2_000;
/** The data link keeps collecting this long after the candidate it waited for came (a call too). */
export const DATA_SETTLE_MS = 150;
/**
 * A connection with no candidate at all by then has stalled: Chromium, rarely and under load, gathers none, and an
 * offer or answer without one can never connect. It is made again in its place, up to `GATHER_ATTEMPTS` in all.
 */
export const GATHER_STALL_MS = 3_000;
export const GATHER_ATTEMPTS = 3;
/** How long a connection may stay `disconnected` before it is given up. */
const DISCONNECT_GRACE_MS = 12_000;
/**
 * An answer whose connection failed, while the peer still offers (`offerStanding`), is made again for the same offer,
 * up to this many times. The offerer's connection waits for an answer for its whole attempt (`CONNECT_TIMEOUT_MS`), and
 * its read of the answer may be held back by its relays' budget; the answerer's ICE gives up after about 30 s of no
 * reply. Going idle then left the link with an offer this side had answered once and would not answer again, until the
 * offerer's attempt ran out: a community's edge was live again 110 s after a member restarted (2026-09-30).
 */
export const REANSWERS = 2;
/**
 * An answer to this side's offer that could not be applied, its connection failing as it was (libdatachannel 0.24.5,
 * in node-datachannel 0.33.4: the answerer's DTLS handshake can end inside setRemoteDescription, before the answer's
 * fingerprint is in, and the connection closes), is followed by a new offer at once, up to this many times until a
 * connection opens. The answerer is there; it was the dial after it that waited: its backoff, 40 s, then its next
 * look (a member let in to a group reached one of its members 72 s after its welcome on CI, 2026-10-06). Two were
 * not enough: on CI the race refused an answer again right after two others, and the edge waited 160 s for its
 * backoff (meshSignals, PR #1363). Offers through members cost no relay request; over the relays four is still a few.
 */
export const ANSWER_REFUSED_REDIALS = 4;
/**
 * The same race a moment later: setRemoteDescription resolves, and the connection closes right after it (8 ms on a
 * loaded core). A connection that ends within this long of its answer going in was refused too: no network fails one
 * that soon (ICE gives up after tens of seconds), so it says nothing about direct connections (`DirectEvidence`).
 * Taken for a network that lets none through, an edge between two CLIs left WebRTC for the run, and a member whose
 * app has WebRTC alone (one from before native group links) was never reached again (groupCompat, 2026-10-12).
 */
const ANSWER_REFUSED_AFTER_MS = 1_000;
/** An offer this close to the end of the offerer's attempt is not answered again: the new answer would come too late. */
const REANSWER_MARGIN_MS = 15_000;

/**
 * Traces the candidate pair an opened data link uses, by type only (host, srflx, prflx, relay; never an address): two
 * devices on one network should meet host to host. A connection without stats (a test's fake) traces nothing.
 */
async function tracePair(me: string, pc: RTCPeerConnection): Promise<void> {
  try {
    if (typeof pc.getStats !== "function") return;
    const stats = await pc.getStats();
    const byId = new Map<string, Record<string, unknown>>();
    stats.forEach((s: Record<string, unknown>) => byId.set(s.id as string, s));
    let pairId: unknown;
    for (const s of byId.values()) if (s.type === "transport" && s.selectedCandidatePairId) pairId = s.selectedCandidatePairId;
    const pair = pairId !== undefined ? byId.get(pairId as string)
      : [...byId.values()].find((s) => s.type === "candidate-pair" && s.nominated && s.state === "succeeded");
    if (!pair) return;
    const kind = (id: unknown) => byId.get(id as string)?.candidateType ?? "?";
    const rtt = typeof pair.currentRoundTripTime === "number" ? Math.round(pair.currentRoundTripTime * 1000) : undefined;
    traceLink(me, "rtc-pair", { local: kind(pair.localCandidateId), remote: kind(pair.remoteCandidateId), ...(rtt !== undefined && { rttMs: rtt }) });
  } catch { /* the trace must not fail the link */ }
}

export class DataLink {
  state: DataLinkState = "idle";
  private pc: RTCPeerConnection | null = null;
  private myOfferTs = 0;
  /**
   * An offer or answer of this side's that went without a public candidate came to nothing (both descriptions were
   * exchanged, and no path connected): the next one waits for its STUN servers as long as it takes
   * (`ICE_GATHERING_TIMEOUT_MS`).
   */
  private fullGather = false;
  /** The offer or answer out has no public candidate (as it went: the connection's description gains any that come later). */
  private sentLacksPublic = false;
  private lastSignalTs = 0;
  /** The peer's description as this connection was given it: Chrome shows it as `remoteDescription` only once applied. */
  private remoteSdp: string | null = null;
  /** When the connection had both descriptions (`connecting`). */
  private connectingSince = 0;
  private connectTimer: ReturnType<typeof setTimeout> | null = null;
  private disconnectTimer: ReturnType<typeof setTimeout> | null = null;
  /** The offer this side answered in the current attempt, when it took it (this clock), and how many times it answered it again. */
  private answered: { offer: RtcSignal; at: number; again: number } | null = null;
  /** Answers refused since a connection last opened, each followed by a new offer at once (`ANSWER_REFUSED_REDIALS`). */
  private refusedAnswers = 0;
  /** The last answer dropped as not for this side's offer (`answer-dropped`): each is said once. */
  private droppedAnswerTs = 0;

  constructor(private readonly options: DataLinkOptions) {}

  /** Offers a connection to the peer. Resolves once the offer is published. */
  /**
   * Makes an offer and publishes it. `gate`: gathered ahead, while the caller still finds out whether the peer is there
   * (a joiner reading the inviter's record): the link stays idle meanwhile, and the offer goes once the gate says yes.
   * On no, the connection is dropped, nothing having been said, and `"held"` is the answer.
   */
  async connect(gate?: Promise<boolean>): Promise<"held" | void> {
    if (this.state !== "idle") return;
    this.answered = null;
    if (!gate) { this.setState("offering"); this.options.setFastPoll(true, true); }
    try {
      const pc = await this.gathered(true, async (pc) => { await pc.setLocalDescription(await pc.createOffer()); });
      if (!pc) return;
      if (gate) {
        const go = await gate;
        // The peer's offer came meanwhile (it was answered), or the link was closed.
        if (this.pc !== pc || this.state !== "idle") return;
        if (!go) { this.teardown(); return "held"; }
        this.setState("offering");
        this.options.setFastPoll(true, true);
      }

      this.myOfferTs = Date.now();
      this.sentLacksPublic = !PUBLIC_CANDIDATE.test(pc.localDescription?.sdp ?? "");
      const signal: RtcSignal = { t: "o", ts: this.myOfferTs, ...extractRtcParams(pc.localDescription!.sdp) };
      this.options.publishSignal(JSON.stringify(signal));
    } catch {
      this.reset();
    }
  }

  /**
   * Feeds a decrypted `_rtc` value from the peer's packet. `sight`: how this device saw it come (`SignalSight`): the
   * peer's record did not carry it at a read the network answered, or it came on a live session just now.
   *
   * The peer's `ts` orders its signals (a later one replaces an earlier one, and an answer names the offer it is for).
   * It is not what says a signal is recent when this device saw it come: two clocks a few minutes apart are common, and
   * every signal of such a peer was dropped here, without a word. An answer is for the offer it names, which this side
   * made in this attempt, so it has no age to check. An offer is as old as the time since the read that did not have it
   * (`offerIsFresh`); only one the first read finds is judged by its own time, as nothing else dates it.
   *
   * A signal dated more than `RTC_SIGNAL_FUTURE_MS` ahead of this clock is not taken at all: taken, its time would
   * be the latest this link knows of the peer, and every signal the peer makes after it would read as older.
   */
  async handleSignal(json: string, sight?: SignalSight): Promise<void> {
    const signal = parseRtcSignal(json);
    if (!signal || signal.ts <= this.lastSignalTs) return;
    if (signal.ts > Date.now() + RTC_SIGNAL_FUTURE_MS) {
      traceLink(this.options.myPubKeyZ32, "signal-ahead", { aheadMs: signal.ts - Date.now() });
      return;
    }
    if (signal.t === "o" && !offerIsFresh(signal.ts, sight)) {
      traceLink(this.options.myPubKeyZ32, "offer-stale", { ageMs: Date.now() - signal.ts, ...(sight && { sinceMs: Date.now() - sight.since, ...(sight.after !== null && { beforePacketMs: sight.after - signal.ts }) }) });
      return;
    }

    if (signal.t === "o") {
      if (this.state === "offering") {
        // Both sides offered at once: the lower public key keeps its offer.
        if (this.options.myPubKeyZ32 < this.options.peerPubKeyZ32) return;
      }
      // A fresh offer while connected means the peer lost the old connection. One that comes while an earlier one is
      // still being answered takes its place too: the peer gave that one up (its answer was refused there, say, and
      // it offered again at once), and a signal is fed once, so a newer offer left aside here was never answered.
      this.lastSignalTs = signal.ts;
      const wasOpen = this.state === "open";
      this.teardown();
      if (wasOpen) { this.options.onDirect?.("closed"); this.options.onClose(); }
      this.answered = { offer: signal, at: Date.now(), again: 0 };
      await this.answer(signal);
    } else if (this.state === "connecting" && this.myOfferTs && signal.o === this.myOfferTs && this.pc) {
      // A newer answer to the offer this side already took an answer for: the answerer made it again (`REANSWERS`),
      // its connection for the one applied here is gone, and this one can never come up. It is given up now, rather
      // than at the end of its attempt (a hub that read a member's first answer late held a dead one 40 s, 2026-09-30).
      traceLink(this.options.myPubKeyZ32, "answer-replaced", { appliedMs: signal.ts - this.lastSignalTs });
      this.lastSignalTs = signal.ts;
      this.reset();
      this.options.onAnswerReplaced?.();
    } else if (this.state === "offering" && signal.o === this.myOfferTs && this.pc) {
      this.lastSignalTs = signal.ts;
      const pc = this.pc;
      try {
        this.remoteSdp = buildDataSdp(signal);
        await pc.setRemoteDescription({ type: "answer", sdp: this.remoteSdp });
        // On a quick path the channel is open before this resolves: never step back from open.
        if (this.pc === pc && this.state === "offering") this.setState("connecting");
      } catch (error) {
        if (this.pc === pc) this.answerRefused(error);
      }
    } else if (signal.t === "a" && signal.ts !== this.droppedAnswerTs) {
      // An answer to an offer this side no longer waits on (one it made before, given up when its answer was refused),
      // or one that came while this side was not offering: dropped, and said once, or a link that waited on its next
      // answer after it showed nothing of why (meshSignals on CI, 2026-10-09).
      this.droppedAnswerTs = signal.ts;
      traceLink(this.options.myPubKeyZ32, "answer-dropped", { state: this.state, ...(this.myOfferTs && signal.o !== undefined ? { offerMs: signal.o - this.myOfferTs } : {}) });
    }
  }

  /**
   * On a quick path the channel opens before setRemoteDescription resolves (see `handleSignal`), when the connection
   * does not show the answer yet: the one it was given counts, as DTLS already checked the peer against it.
   */
  get fingerprints(): [string, string] | null {
    const local = this.pc?.localDescription?.sdp;
    const remote = this.pc?.remoteDescription?.sdp ?? (this.pc ? this.remoteSdp : null);
    if (!local || !remote) return null;
    try { return [extractRtcParams(local).f.toLowerCase(), extractRtcParams(remote).f.toLowerCase()]; }
    catch { return null; }
  }

  close(): void {
    // Given up for another transport that went live while this one had long had both descriptions: evidence all the same.
    const stalled = Date.now() - this.connectingSince >= STALLED_EVIDENCE_MS;
    const evidence = stalled ? this.directEvidence() : null;
    this.noteNoPublic(stalled);
    this.answered = null;
    this.reset();
    if (evidence) this.options.onDirect?.(evidence);
  }

  /**
   * This side's offer went with no public candidate and was answered, or its answer went with none, and it came to
   * nothing: the next offer or answer gathers for as long as it takes.
   */
  private noteNoPublic(ended: boolean): void {
    if (ended && (this.myOfferTs || this.answered) && this.sentLacksPublic && this.state === "connecting") this.fullGather = true;
  }

  /**
   * What this attempt says about direct connections if it ends now without opening: nothing unless both descriptions
   * were exchanged (this side's offer answered, or its answer out). Then, what this device gathered: no public
   * candidate, a public port per STUN server, or (for the side that offered) candidates that read as reachable.
   */
  private directEvidence(): DirectEvidence | null {
    if (this.state !== "connecting" || !this.pc) return null;
    const local = this.pc.localDescription?.sdp ?? "";
    return !PUBLIC_CANDIDATE.test(local) ? "no-public" : symmetricNat(local) ? "symmetric" : this.myOfferTs ? "no-path" : null;
  }

  /**
   * The attempt on this connection failed (it timed out, ICE failed or closed, its channel closed). An answer the
   * offerer may not have read yet is made again for the same offer while it still stands (`REANSWERS`); anything
   * else goes back to idle. `byConnection`: the connection said so itself, rather than a timer of this link's.
   */
  private failed(byConnection = false): void {
    // The connection failed while the answer to this side's offer was being applied: as if it was refused.
    if (this.state === "offering" && this.remoteSdp) { this.answerRefused("failed"); return; }
    // The same when the connection ends a moment after the answer went in (`ANSWER_REFUSED_AFTER_MS`).
    if (byConnection && this.state === "connecting" && this.myOfferTs && Date.now() - this.connectingSince < ANSWER_REFUSED_AFTER_MS) { this.answerRefused("failed"); return; }
    const answered = this.state === "connecting" ? this.answered : null;
    // How long the offerer's attempt still runs, counted on this clock from when its offer was taken (its `ts` is its clock's).
    const left = answered ? CONNECT_TIMEOUT_MS - (Date.now() - answered.at) : 0;
    // An answer to an offer the offerer has given up since (its packet no longer carries it: the answer was refused
    // there, say) connected nothing because nobody was on the other end, whatever the network lets through.
    const givenUp = !!answered && this.options.offerStanding?.(answered.offer.ts) === false;
    const evidence = givenUp ? null : this.directEvidence();
    this.noteNoPublic(!givenUp);
    if (answered && answered.again < REANSWERS && left > REANSWER_MARGIN_MS && this.options.offerStanding?.(answered.offer.ts)) {
      answered.again++;
      traceLink(this.options.myPubKeyZ32, "reanswer", { again: answered.again, leftMs: left });
      this.teardown();
      void this.answer(answered.offer);
      return;
    }
    this.reset();
    if (evidence) this.options.onDirect?.(evidence);
  }

  /** The answer to this side's offer did not go in (`ANSWER_REFUSED_REDIALS`): the attempt ends, and the caller may offer again now. */
  private answerRefused(error: unknown): void {
    const again = this.refusedAnswers < ANSWER_REFUSED_REDIALS;
    traceLink(this.options.myPubKeyZ32, "answer-refused", { error: error instanceof Error ? error.message : String(error), again });
    this.reset();
    if (!again) { this.options.onAnswersRefused?.(); return; }
    this.refusedAnswers++;
    this.options.onAnswerReplaced?.();
  }

  private async answer(offer: RtcSignal): Promise<void> {
    this.setState("answering");
    this.options.setFastPoll(true);
    try {
      const pc = await this.gathered(false, async (pc) => {
        await pc.setRemoteDescription({ type: "offer", sdp: buildDataSdp(offer) });
        await pc.setLocalDescription(await pc.createAnswer());
      });
      if (!pc) return;

      this.sentLacksPublic = !PUBLIC_CANDIDATE.test(pc.localDescription?.sdp ?? "");
      const signal: RtcSignal = {
        t: "a",
        ts: Date.now(),
        o: offer.ts,
        ...extractRtcParams(pc.localDescription!.sdp),
      };
      this.options.publishSignal(JSON.stringify(signal));
      this.setState("connecting");
    } catch {
      // A newer offer took this one's place meanwhile (its connection was closed under it): that attempt goes on.
      if (this.answered?.offer === offer) this.reset();
    }
  }

  /**
   * Makes the connection (`describe` sets its description) and waits for its candidates. One that found none by
   * `GATHER_STALL_MS` is replaced by a new one, up to `GATHER_ATTEMPTS` in all; when none finds any, the link goes back
   * to idle at once rather than hold, for its whole timeout, an attempt that cannot connect. Null when the link moved
   * on meanwhile (closed, or another signal took over) or gave up.
   */
  private async gathered(offer: boolean, describe: (pc: RTCPeerConnection) => Promise<void>): Promise<RTCPeerConnection | null> {
    let stalled: RTCPeerConnection | null = null;
    for (let attempt = 1; ; attempt++) {
      // The new connection takes the old one's place first: closing that one then resets nothing.
      const pc = this.createConnection();
      stalled?.close();
      await describe(pc);
      if (this.pc !== pc) return null;
      const gathering = Date.now();
      await waitForIceGathering(pc, ICE_GATHERING_TIMEOUT_MS,
        { stallMs: GATHER_STALL_MS, settleMs: DATA_SETTLE_MS, ...(!this.fullGather ? { hostBoundMs: OFFER_HOST_GATHER_MS } : {}) });
      if (this.pc !== pc) return null;
      const ms = Date.now() - gathering;
      if (sdpHasCandidates(pc.localDescription?.sdp)) {
        traceLink(this.options.myPubKeyZ32, "ice-gathered", { ms, offer, ...(attempt > 1 ? { attempt } : {}) });
        return pc;
      }
      traceLink(this.options.myPubKeyZ32, "ice-stalled", { ms, offer, attempt });
      if (attempt >= GATHER_ATTEMPTS) { this.reset(); this.options.onDirect?.("no-public"); return null; }
      stalled = pc;
    }
  }

  private createConnection(): RTCPeerConnection {
    const pc = this.options.createPeerConnection();
    this.pc = pc;

    // Negotiated channel: both sides declare it, no in-band open handshake.
    const dc = pc.createDataChannel(DATA_CHANNEL_LABEL, { negotiated: true, id: DATA_CHANNEL_ID, ordered: true });
    dc.addEventListener("open", () => {
      if (this.pc !== pc) return;
      this.clearTimers();
      this.answered = null;
      this.refusedAnswers = 0;
      this.fullGather = false;
      this.setState("open");
      this.options.setFastPoll(false);
      this.options.publishSignal(null);
      this.options.onDirect?.("open");
      this.options.onOpen(wrapDataChannel(dc));
      void tracePair(this.options.myPubKeyZ32, pc);
    });
    dc.addEventListener("close", () => {
      if (this.pc === pc) this.failed(true);
    });

    pc.addEventListener("connectionstatechange", () => {
      if (this.pc !== pc) return;
      if (this.disconnectTimer) { clearTimeout(this.disconnectTimer); if (pc.connectionState === "connected") this.options.onDisconnected?.(false); }
      this.disconnectTimer = null;
      if (pc.connectionState === "failed" || pc.connectionState === "closed") this.failed(true);
      else if (pc.connectionState === "disconnected") {
        if (this.state === "open") this.options.onDisconnected?.(true);
        this.disconnectTimer = setTimeout(() => {
          if (this.pc === pc) this.failed();
        }, DISCONNECT_GRACE_MS);
      }
    });

    this.startAttemptTimer(pc);
    return pc;
  }

  /** The attempt on `pc` gives up this long from now (`CONNECT_TIMEOUT_MS`) unless it opens. */
  private startAttemptTimer(pc: RTCPeerConnection): void {
    if (this.connectTimer) clearTimeout(this.connectTimer);
    this.connectTimer = setTimeout(() => {
      if (this.pc === pc && this.state !== "open") {
        traceLink(this.options.myPubKeyZ32, "attempt-timeout", { state: this.state });
        this.failed();
      }
    }, this.options.attemptTimeoutMs?.() ?? CONNECT_TIMEOUT_MS);
  }

  /**
   * This side's offer or answer reached the relays only now (their budget, or an outage, held it back): the attempt
   * counts from here, so the other side has as long to read it as if it had gone out at once.
   */
  signalWentOut(): void {
    if (this.pc && this.connectTimer && this.state !== "open" && this.state !== "idle") this.startAttemptTimer(this.pc);
  }

  private clearTimers(): void {
    if (this.connectTimer) clearTimeout(this.connectTimer);
    if (this.disconnectTimer) clearTimeout(this.disconnectTimer);
    this.connectTimer = this.disconnectTimer = null;
  }

  private teardown(): boolean {
    this.clearTimers();
    const pc = this.pc;
    this.pc = null;
    this.myOfferTs = 0;
    this.remoteSdp = null;
    if (!pc) return false;
    pc.close();
    return true;
  }

  private reset(): void {
    const wasOpen = this.state === "open";
    const hadConnection = this.teardown();
    if (this.state === "idle" && !hadConnection) return;
    this.setState("idle");
    this.options.setFastPoll(false);
    this.options.publishSignal(null);
    if (wasOpen) { this.options.onDirect?.("closed"); this.options.onClose(); }
  }

  private setState(state: DataLinkState): void {
    if (this.state === state) return;
    this.state = state;
    if (state === "connecting") this.connectingSince = Date.now();
    this.options.onState?.(state);
  }
}
